DECLARE p jsonb := $payload${"ley":{"id":"84446660-e33c-512f-9975-57527758c6c7","titulo":"Acuerdo por el que se emite la modificación a la Convocatoria para la atención prioritaria de solicitudes de permisos de generación eléctrica e interconexión al Sistema Eléctrico Nacional, alineados a la planeación vinculante [DOF 02/12/2025]","siglas":"CONV-GEN-1-M3","fecha_publicacion":"2025-12-02","fecha_ultima_reforma":null,"vigente":null,"temas_clave":["Primera convocatoria de generación","Convocatorias","Modificación","Interconexión"],"url_original":"https://sidof.segob.gob.mx/notas/docFuente/5774850","tipo":"acuerdo"},"articulos":[{"id":"111a3ab4-cb8b-5ddf-910c-caf05f0c0ca5","ley_id":"84446660-e33c-512f-9975-57527758c6c7","orden":0,"identificador":"Nota editorial · versiones relacionadas","contenido":"### Nota editorial · versión publicada y documentos relacionados\n\nEste registro reproduce la publicación del DOF de 02/12/2025. Se conserva el texto de esa publicación; las modificaciones se consultan en registros separados. No es un texto consolidado ni una indicación de que todos sus plazos permanezcan abiertos.\n\nDocumentos de la misma convocatoria incorporados al acervo:\n\n- <a href=\"/#ley-b09aa69b-381d-56ee-890d-53c42a98565f\" target=\"_blank\" rel=\"noopener noreferrer\">Texto original · 17/10/2025</a> · [fuente oficial](https://sidof.segob.gob.mx/notas/docFuente/5770299)\n- <a href=\"/#ley-e49973bd-aae7-5038-8cb6-37a9f1c00f3a\" target=\"_blank\" rel=\"noopener noreferrer\">Modificación 1 · 24/10/2025</a> · [fuente oficial](https://sidof.segob.gob.mx/notas/docFuente/5770917)\n- <a href=\"/#ley-10c059c7-bfa4-5ec0-9ae6-bf1d8a35a637\" target=\"_blank\" rel=\"noopener noreferrer\">Modificación 2 · 10/11/2025</a> · [fuente oficial](https://sidof.segob.gob.mx/notas/docFuente/5772392)\n- <a href=\"/#ley-84446660-e33c-512f-9975-57527758c6c7\" target=\"_blank\" rel=\"noopener noreferrer\">Modificación 3 · 02/12/2025</a> · [fuente oficial](https://sidof.segob.gob.mx/notas/docFuente/5774850)\n\nEsta nota es información editorial del buscador y no forma parte de la publicación oficial. Referencias del radar con corte al 14 de septiembre de 2026, cotejadas para esta incorporación.\n","tipo_articulo":"complementario","titulo_nombre":"Información editorial de la versión","capitulo_nombre":null,"seccion_nombre":null},{"id":"186a84a9-83f5-579b-ac80-2e38ce254804","ley_id":"84446660-e33c-512f-9975-57527758c6c7","orden":1,"identificador":"Preámbulo del acuerdo modificatorio","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n ACUERDO por el que se emite la modificación a la Convocatoria para la atención prioritaria de solicitudes de permisos de generación eléctrica e interconexión al Sistema Eléctrico Nacional, alineados a la planeación vinculante.\n Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Secretaría de Energía.\n<div> LUZ ELENA GONZÁLEZ ESCOBAR, Secretaria de Energía, con fundamento en lo dispuesto por los artículos 28, párrafo noveno, 90, párrafo primero, de la Constitución Política de los Estados Unidos Mexicanos; 2, fracción I, 14, párrafo primero, 26, fracción IX y 33, fracciones IV, V, XXXI y XXXIII de la Ley Orgánica de la Administración Pública Federal; 4, de la Ley Federal de Procedimiento Administrativo;  57 del Reglamento de la Ley de Planeación y Transición Energética; 3 y Transitorio Vigésimo Primero del Reglamento de la Ley del Sector Eléctrico, y</div>\n<div> CONSIDERANDO<br> </div>\n<div> Que el 17 de octubre de 2025 en el Diario Oficial de la Federación se publicó la &quot;CONVOCATORIA PARA LA ATENCIÓN PRIORITARIA DE SOLICITUDES DE PERMISOS DE GENERACIÓN ELÉCTRICA E INTERCONEXIÓN AL SISTEMA ELÉCTRICO NACIONAL, ALINEADOS A LA PLANEACIÓN VINCULANTE&quot; (Convocatoria), dirigida a las personas particulares, para la presentación de solicitudes de permisos de generación para el desarrollo de centrales eléctricas que son estratégicas y prioritarias en la planeación vinculante del sector eléctrico hasta el 2030.</div>\n<div> Que derivado del interés de las personas particulares respecto de la Convocatoria, el 24 de octubre de 2025, fue publicado en el Diario Oficial de la Federación el &quot;Acuerdo por el que se emite la modificación a la Convocatoria para la atención prioritaria de solicitudes de permisos de generación eléctrica e interconexión al Sistema Eléctrico Nacional, alineados a la planeación vinculante, publicada en la edición vespertina del 17 de octubre de 2025&quot;, a efecto de realizar modificaciones a las fechas del calendario establecido en la Convocatoria.</div>\n<div> Que el 10 de noviembre de 2025 se publicó en el Diario Oficial de la Federación el &quot;Acuerdo por el que se emite la modificación a la Convocatoria para la Atención Prioritaria de Solicitudes de Permisos de Generación Eléctrica e Interconexión al Sistema Eléctrico Nacional, alineados a la planeación vinculante&quot; con la finalidad de que las personas interesadas en participar en la Convocatoria cuenten con un periodo adicional para realizar el pago correspondiente de los estudios realizados por el Centro Nacional de Control de Energía.</div>\n<div> Que en congruencia con lo anterior, se debe facilitar a quienes se otorguen los permisos de generación de energía eléctrica derivado de la Convocatoria, la presentación y acreditación ante el Centro Nacional de Control de Energía de las garantías necesarias para solicitar la suscripción del contrato de interconexión correspondiente.</div>\n<div> Derivado de lo anterior, se considera oportuno realizar la modificación en los plazos para la presentación de las garantías, proporcionando un ajuste para que las personas interesadas exhiban las garantías que se requieren para solicitar la suscripción del contrato de interconexión y estableciendo dicha condición en el contenido del formato de aceptación de obras que se debe presentar, por lo que he tenido a bien emitir el siguiente:</div>\n<div> ACUERDO POR EL QUE SE EMITE LA MODIFICACIÓN A LA CONVOCATORIA PARA LA ATENCIÓN<br> PRIORITARIA DE SOLICITUDES DE PERMISOS DE GENERACIÓN ELÉCTRICA E INTERCONEXIÓN<br> AL SISTEMA ELÉCTRICO NACIONAL, ALINEADOS A LA PLANEACIÓN VINCULANTE<br> </div>","tipo_articulo":"preambulo","titulo_nombre":"Primera convocatoria de generación · publicación del 02-12-2025","capitulo_nombre":null,"seccion_nombre":null},{"id":"e4d70979-4478-5c01-a3c6-6bcc7dc15106","ley_id":"84446660-e33c-512f-9975-57527758c6c7","orden":2,"identificador":"Resolutivo PRIMERO","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> PRIMERO. Se modifica el numeral ii, del apartado C, del numeral 8. Aprobación y emisión de permisos de generación de energía eléctrica, así como publicación de los resultados de la &quot;CONVOCATORIA PARA LA ATENCIÓN PRIORITARIA DE SOLICITUDES DE PERMISOS DE GENERACIÓN ELÉCTRICA E INTERCONEXIÓN AL SISTEMA ELÉCTRICO NACIONAL, ALINEADOS A LA PLANEACIÓN VINCULANTE&quot;, para quedar en los siguientes términos:</div>\n<div> 8. Aprobación y emisión de permisos de generación de energía eléctrica, así como publicación de los resultados.</div>\n<div> A. a la B. ...</div>\n<div> C. Emisión de los títulos de permisos.</div>\n<div> ...</div>\n<div> ...</div>\n<div> i.      ...</div>\n<div> ii.     Acreditar, previo a la firma del contrato de interconexión correspondiente, la presentación de la garantía por las obras de refuerzo resultado del estudio de instalaciones que hayan aceptado ante el CENACE.</div>\n<div> iii. a v.</div>\n<div> D. ...</div>","tipo_articulo":"ordinario","titulo_nombre":"Primera convocatoria de generación · publicación del 02-12-2025","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":null},{"id":"0d103f90-8b3a-5a24-9a69-17cd48b6841a","ley_id":"84446660-e33c-512f-9975-57527758c6c7","orden":3,"identificador":"Resolutivo SEGUNDO","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> SEGUNDO. Se modifica el Anexo d. Formato Aceptación de Obras de la &quot;CONVOCATORIA PARA LA ATENCIÓN PRIORITARIA DE SOLICITUDES DE PERMISOS DE GENERACIÓN ELÉCTRICA E INTERCONEXIÓN AL SISTEMA ELÉCTRICO NACIONAL, ALINEADOS A LA PLANEACIÓN VINCULANTE&quot;, para quedar como sigue:</div>\n<div> d. Formato Aceptación de Obras:</div>\n<table> <tbody><tr> <td> <div> CARTA DE ACEPTACIÓN DE OBRAS<br> </div> <div> Ciudad de México, a [fecha de presentación]<br> </div> <div> A quien corresponda,</div> <div> El suscriptor de la presente, C. [_] en mi carácter de representante [legal / apoderado], de la persona moral denominada [_], señalando para oír y recibir todo tipo de notificaciones y documentos el domicilio ubicado en: [_], y autorizando para los mismos efectos a los señores: [_]; en este acto comparezco para exponer:</div> <div> Que en nombre de mi representada y en ejercicio de las facultades que me fueron conferidas, manifiesto de manera expresa y libre de vicios del consentimiento, la voluntad para aceptar los resultados del o los Estudios correspondientes a la Solicitud de Interconexión N° [_] de fecha [_] notificado a mi representada mediante oficio número [_], en el que se establece la necesidad de realizar las inversiones e infraestructura estimada por el Centro Nacional de Control de Energía (CENACE), por la cantidad de [_].</div> <div> En virtud de lo anterior, con la suscripción de este formato, mi representada se obliga unilateralmente y de manera incondicional a pagar al CENACE, la cantidad de [_], en caso de incumplimiento de las obligaciones relacionadas con: (i) Ejecutar y terminar la construcción de las Obras de Interconexión y Obras de Refuerzo de conformidad con las Características Específicas de la Infraestructura Requerida para la Interconexión de la central eléctrica determinadas en el o los Estudios, (ii) Iniciar las operaciones de Interconexión en la fecha de entrada en operación, (iii) Realizar los actos que el CENACE indique de conformidad con los Estudios previamente realizados, y (iv) Cumplir con la normatividad aplicable a la Red Nacional de Transmisión y las Redes Generales de Distribución, así como con las Disposiciones Administrativas de Carácter General que contienen los criterios de eficiencia, calidad, confiabilidad, continuidad, seguridad y sustentabilidad del Sistema Eléctrico Nacional: Código de Red.</div> <div> De conformidad con lo señalado en la &quot;Convocatoria para la atención prioritaria de solicitudes de permisos de generación eléctrica e interconexión al Sistema Eléctrico Nacional, alineados a la planeación vinculante&quot;,  (La Convocatoria), publicada en el Diario Oficial de la Federación el día [_], así como el &quot;Manual para la Interconexión de Centrales Eléctricas y Conexión de Centros de Carga&quot; (el &quot;Manual de Interconexión y Conexión&quot;) y para efectos de asegurar el cumplimiento concurrente de las obligaciones antes referidas, mi representada en este acto, se compromete, en caso de que el Comité Técnico de la CNE determine la aprobación del permiso de generación de energía eléctrica por haber cumplido con los requisitos establecidos en La Convocatoria, otorgar una garantía; [ (a) dinero en efectivo, mediante depósito bancario de dinero a la vista en la cuenta bancaria número [_] a nombre del fideicomiso N° [_]; (b) Certificados de Tesorería de la Federación por la cantidad de [_] y/o (c) Carta de Crédito Stand By por la cantidad de [_], que cumple con el formato establecido en el Manual de Interconexión de Centrales Eléctricas y Conexión de Centros de Carga, y presentarla previo a la firma del contrato de interconexión correspondiente.</div> <div> Por lo expuesto atentamente solicito:</div> <div> PRIMERO. Se tenga por acreditada la personalidad con que me ostento, representando legalmente a la persona moral denominada [_].</div> <div> SEGUNDO. Se me tenga por presentado en nombre de mi representada el presente formato de aceptación de obras, para responder por el debido cumplimiento de todas y cada una de las obligaciones aquí consignadas y relacionadas con el o los estudios elaborados con motivo de la Solicitud No. [_], los cuales me fueron notificados mediante oficio No. [_] de fecha [_].</div> <div> TERCERO. Se me tenga por presentado en nombre de mi representada aceptando todos y cada uno de los términos, condiciones y plazos establecidos en La Convocatoria.</div> <div> CUARTO. Se acuerde la aceptación de promesa de la garantía por el monto requerido, misma que se presentará formalmente por parte de mi representada previo a la firma del contrato de interconexión correspondiente.</div> <div> Atentamente</div> <div> NOMBRE Y FIRMA DE LA PERSONA QUE SUSCRIBE LA CARTA</div> <div>  </div> </td> </tr> </tbody></table>","tipo_articulo":"ordinario","titulo_nombre":"Primera convocatoria de generación · publicación del 02-12-2025","capitulo_nombre":"Resolutivo SEGUNDO del acuerdo modificatorio","seccion_nombre":null},{"id":"cc999964-58c8-5269-8ad0-2bc033d70a7c","ley_id":"84446660-e33c-512f-9975-57527758c6c7","orden":4,"identificador":"Transitorio ÚNICO · acuerdo","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> TRANSITORIO<br> </div>\n<div> ÚNICO. El presente Acuerdo entra en vigor el mismo día de su publicación en el Diario Oficial  de la Federación.</div>","tipo_articulo":"transitorio","titulo_nombre":"Primera convocatoria de generación · publicación del 02-12-2025","capitulo_nombre":"Transitorios del acuerdo modificatorio","seccion_nombre":null},{"id":"fde20a9e-8665-5516-801c-10ab4b4e6d72","ley_id":"84446660-e33c-512f-9975-57527758c6c7","orden":5,"identificador":"Firma del acuerdo","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> Ciudad de México, a 28 de noviembre de 2025.- Secretaria de Energía, Luz Elena González Escobar.- Rúbrica.</div>","tipo_articulo":"complementario","titulo_nombre":"Primera convocatoria de generación · publicación del 02-12-2025","capitulo_nombre":"Documentos complementarios","seccion_nombre":null}],"temas":[{"nivel":"titulo","nombre":"Información editorial de la versión","orden":0},{"nivel":"capitulo","nombre":"Resolutivo PRIMERO del acuerdo modificatorio","orden":1},{"nivel":"capitulo","nombre":"Resolutivo SEGUNDO del acuerdo modificatorio","orden":2},{"nivel":"capitulo","nombre":"Transitorios del acuerdo modificatorio","orden":3}],"fuente":{"name":"CONV-GEN-1-M3","code":"5774850","radar":"RAD-029","familia":"Primera convocatoria de generación","modificacion":3,"url":"https://sidof.segob.gob.mx/notas/docFuente/5774850","sha256":"80ee13b6af8ee224200c33f18a6cb5426fff88a23f61ddcf90b1eec9e91debfe","fecha":"02-12-2025","titulo":"Acuerdo por el que se emite la modificación a la Convocatoria para la atención prioritaria de solicitudes de permisos de generación eléctrica e interconexión al Sistema Eléctrico Nacional, alineados a la planeación vinculante.","codDiario":324425,"pagina":70,"tables":1,"images":[]}}$payload$::jsonb; lid uuid;
BEGIN
 lid := (p->'ley'->>'id')::uuid;
 LOCK TABLE public.leyes,public.articulos,public.temas IN SHARE ROW EXCLUSIVE MODE;
 IF EXISTS(SELECT 1 FROM public.leyes WHERE id=lid OR lower(siglas)=lower(p->'ley'->>'siglas') OR lower(titulo)=lower(p->'ley'->>'titulo') OR url_original=p->'ley'->>'url_original') THEN RAISE EXCEPTION 'El instrumento ya existe: revisar, no reemplazar'; END IF;
 INSERT INTO public.leyes(id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo) SELECT id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo FROM jsonb_populate_record(null::public.leyes,p->'ley');
 INSERT INTO public.articulos(id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden) SELECT id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden FROM jsonb_populate_recordset(null::public.articulos,p->'articulos');
 INSERT INTO public.temas(ley_id,nivel,nombre,orden) SELECT lid,t->>'nivel',t->>'nombre',(t->>'orden')::int FROM jsonb_array_elements(p->'temas')t;
 IF (SELECT count(*)FROM public.articulos WHERE ley_id=lid)<>jsonb_array_length(p->'articulos') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'articulos')b LEFT JOIN public.articulos a ON a.id=(b->>'id')::uuid WHERE a.id IS NULL OR (to_jsonb(a)-'fts'-'created_at') IS DISTINCT FROM b) THEN RAISE EXCEPTION 'Fallo de cotejo exacto de artículos'; END IF;
 IF (SELECT count(*)FROM public.temas WHERE ley_id=lid)<>jsonb_array_length(p->'temas') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'temas')b WHERE NOT EXISTS(SELECT 1 FROM public.temas t WHERE ley_id=lid AND (to_jsonb(t)-'id'-'ley_id'-'created_at')=b)) THEN RAISE EXCEPTION 'Fallo de cotejo de estructura'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.leyes l WHERE id=lid AND to_jsonb(l)-'created_at'=p->'ley') THEN RAISE EXCEPTION 'Metadatos diferentes'; END IF;
 IF EXISTS(SELECT 1 FROM public.articulos WHERE ley_id=lid AND (nullif(trim(contenido),'')IS NULL OR fts IS NULL OR fts=''::tsvector)) THEN RAISE EXCEPTION 'Texto o índice FTS vacío'; END IF;
END $ingest$;
COMMIT;
SELECT l.siglas,l.id,(SELECT count(*)FROM public.articulos a WHERE a.ley_id=l.id)fragmentos,(SELECT count(*)FROM public.temas t WHERE t.ley_id=l.id)temas FROM public.leyes l WHERE l.id='84446660-e33c-512f-9975-57527758c6c7';
